classDiagram
    class 데이터수집모듈 {
        +String 제조레시피
        +String 물성데이터
        +수집()
    }
    class 결측치제거모듈 {
        +removeMissingValues()
    }
    class 데이터카테고리화모듈 {
        +categorizeData()
    }
    class 데이터전처리모듈 {
        +splitData()
    }
    class 머신러닝모델학습모듈 {
        +trainModel()
    }
    class 모델검증모듈 {
        +validateModel()
    }
    class 물성예측모듈 {
        +predictProperties()
    }

    데이터수집모듈 --> 결측치제거모듈 : "데이터 수집"
    결측치제거모듈 --> 데이터카테고리화모듈 : "결측치 제거"
    데이터카테고리화모듈 --> 데이터전처리모듈 : "카테고리화"
    데이터전처리모듈 --> 머신러닝모델학습모듈 : "데이터 전처리"
    머신러닝모델학습모듈 --> 모델검증모듈 : "모델 학습"
    모델검증모듈 --> 물성예측모듈 : "모델 검증"
